import{G as e,W as t,n,rt as r}from"./chunks/framework.BVvt2_kn.js";import"./chunks/assets.BZpss8I_.js";var i=JSON.parse(`{"title":"如何申請?","description":"","frontmatter":{},"headers":[],"relativePath":"use.md","filePath":"use.md"}`),a={name:`use.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="如何申請" tabindex="-1">如何申請? <a class="header-anchor" href="#如何申請" aria-label="Permalink to “如何申請?”">​</a></h1><p>在這裡，你會看到申請的步驟，以及申請該給的資訊。</p><h2 id="第一步-開單申請" tabindex="-1">第一步，開單申請 <a class="header-anchor" href="#第一步-開單申請" aria-label="Permalink to “第一步，開單申請”">​</a></h2><p>首先你要到Discord頻道申請伺服器</p><ol><li>加入託管<a href="https://discord.gg/drMFgPb6QJ" target="_blank" rel="noreferrer">Discord伺服器</a></li><li>開單申請 <a href="https://discord.com/channels/1522956743779287141/1528440297628106843" target="_blank" rel="noreferrer">#［托管申請］</a><img src="/assets/ticket.CfoZoCFG.png" alt="An image" width="1032" height="569"></li><li>開啟客服單之後說說明你需要的環境語言.用途.專案邀請連結(Discord機器人).你的Email等資料 . 以及你要的節點位置</li></ol><p><strong>面板選擇 | 強烈推薦使用面板二，面板二的UI較好用</strong></p><p>若您選擇<a href="https://main.wayne227304.dpdns.org/" target="_blank" rel="noreferrer">面板一</a>將是MCSM Panel</p><p>若您選擇<a href="https://panel.wayne227304.dpdns.org/" target="_blank" rel="noreferrer">面板二</a>將是Pterodactyl</p><p><strong>選擇面板一的需自行告訴管理員您要設定密碼</strong></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>墨西哥 - 資源給你隨便用，較麻煩</p><p>台灣 - 資源限制，較方便，且好用</p></div><p><strong>範例</strong></p><div class="language-md"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">您好，我需要一台Python伺服器</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">節點:墨西哥節點</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我的用途為 Discord 機器人</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">這是我的專案邀請連結 : https://......</span></span></code></pre></div><h2 id="第二步-進入面板-面板二" tabindex="-1">第二步，進入面板 (面板二) <a class="header-anchor" href="#第二步-進入面板-面板二" aria-label="Permalink to “第二步，進入面板 (面板二)”">​</a></h2><p>查看電子郵件，若沒有收到電子郵件請到垃圾郵件查看</p><p>看到知道點選那個按鈕，輸入您想要的密碼</p><p><strong>此密碼需記住，管理員無法查看您設定的密碼，但可更改</strong></p><h2 id="第三部-進入面板-註冊-完畢後" tabindex="-1">第三部，進入面板/註冊 完畢後 <a class="header-anchor" href="#第三部-進入面板-註冊-完畢後" aria-label="Permalink to “第三部，進入面板/註冊 完畢後”">​</a></h2><p>裡面就有您的伺服器啦</p><p>點按進去可能會有正在安裝的提示</p><p>請等待他安裝完畢</p><h2 id="其他" tabindex="-1">其他 : <a class="header-anchor" href="#其他" aria-label="Permalink to “其他 :”">​</a></h2><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>若您使用違反服務條款</p><p>以及非正常行為我們將有權將您的伺服器停權</p><p>尤其是墨西哥節點，並且我們不接受資料取回</p></div><h2 id="下一頁" tabindex="-1">下一頁 : <a class="header-anchor" href="#下一頁" aria-label="Permalink to “下一頁 :”">​</a></h2><p>下一頁為「使用須知」</p><p>請點擊「Next page」開始查看教學</p>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};